func (l *RustLexer) Sempred(localctx antlr.RuleContext, ruleIndex, predIndex int) bool {
	switch ruleIndex {
	case 69:
		return l.SHEBANG_Sempred(localctx, predIndex)

	case 90:
		return l.FLOAT_LITERAL_Sempred(localctx, predIndex)

	default:
		panic("No registered predicate for: " + fmt.Sprint(ruleIndex))
	}
}

func (p *RustLexer) SHEBANG_Sempred(localctx antlr.RuleContext, predIndex int) bool {
	this := p
	_ = this

	switch predIndex {
	case 0:
		return p.SOF()

	default:
		panic("No predicate with index: " + fmt.Sprint(predIndex))
	}
}

func (p *RustLexer) FLOAT_LITERAL_Sempred(localctx antlr.RuleContext, predIndex int) bool {
	this := p
	_ = this

	switch predIndex {
	case 1:
		return p.FloatLiteralPossible()

	case 2:
		return p.FloatDotPossible()

	default:
		panic("No predicate with index: " + fmt.Sprint(predIndex))
	}
}
